def read_config_file(filename):
    """Read configuration from a JSON file."""
    import json

    try:
        with open(filename, "r") as f:
            return json.load(f)
    except FileNotFoundError as e:
        raise DataProcessingError(f"Configuration file not found: {filename}") from e
    except json.JSONDecodeError as e:
        raise DataProcessingError(f"Invalid JSON in configuration file") from e

def process_data_with_config(config_file, data):
    """Process data using configuration from file."""
    try:
        config = read_config_file(config_file)
        # Simulate data processing
        if not config:
            raise ValueError("Empty configuration")
        return f"Data processed with config: {config}"
    except DataProcessingError:
        # Re-raise as is
        raise
    except Exception as e:
        # Chain other exceptions
        raise DataProcessingError("Failed to process data") from e

# Test exception chaining
try:
    result = process_data_with_config("nonexistent_config.json", [1, 2, 3])
    print(result)
except DataProcessingError as e:
    print(f"Processing error: {e}")
    print(f"Original cause: {e.__cause__}")
    print(f"Cause type: {type(e.__cause__).__name__}")

print("\n" + "=" * 50 + "\n")

